/* Reading-first chapters. Existing adventure mechanics remain the practice layer. */
'use strict';
const CS=ChapterStudy;
let heldFruit=null;
function currentCourse(s=state){const b=L.bank(s);return b?.syllabus||(b?.id===EXAM_ID?StrategistCourse:null);}
function studyState(){const c=currentCourse();if(!c)return null;state.chapterStudies??={};return state.chapterStudies[L.bank(state).id]??=CS.fresh();}
function studyChapter(){return currentCourse().chapters[studyState().chapter];}
function studySection(){return studyChapter().sections[studyState().section];}
function basicsReady(){const s=studyState();return!!s&&s.submitted.includes(s.chapter);}
function studyLocked(event){toast('还未学完基础知识：先阅读学习素材，完成各节知识装置，再到素材箱交付整章。');const target=event?.currentTarget;if(!target?.getBoundingClientRect)return;const rect=target.getBoundingClientRect();document.getElementById('learningLockBubble')?.remove();const bubble=document.createElement('div');bubble.id='learningLockBubble';bubble.className='learning-lock-bubble';bubble.textContent='基础还没学完，先完成本章各节学习并交付。';bubble.style.left=Math.max(16,Math.min(window.innerWidth-266,rect.left-85))+'px';bubble.style.top=Math.max(80,rect.top-65)+'px';document.body.appendChild(bubble);setTimeout(()=>bubble.remove(),3600);}
const chapterRestore=L.restore;
L.restore=function(raw){const s=chapterRestore(raw);if(!s)return null;try{
 for(const b of s.banks)if(b.syllabus)b.syllabus=CourseSchema.normalize(b.syllabus);
 if(s.chapterStudies){if(typeof s.chapterStudies!=='object'||Array.isArray(s.chapterStudies))return null;for(const[id,progress]of Object.entries(s.chapterStudies)){const b=s.banks.find(b=>b.id===id),course=b?.syllabus||(id===EXAM_ID?StrategistCourse:null);if(!course||!CS.validate(progress,course,b.cards))return null;}}
 for(const[bid,progress]of Object.entries(s.chapterStudies||{}))if(progress.practiceRuns!==undefined){if(!progress.practiceRuns||typeof progress.practiceRuns!=='object'||Array.isArray(progress.practiceRuns))return null;for(const[key,snapshot]of Object.entries(progress.practiceRuns)){if(!/^[0-3]$/.test(key)||!snapshot?.run||!snapshot.play)return null;const b=s.banks.find(b=>b.id===bid),course=b?.syllabus||(bid===EXAM_ID?StrategistCourse:null),allowed=new Set(CS.pool({...progress,chapter:+key},course,b.cards).map(c=>c.id));if(!snapshot.run.cards?.every(id=>allowed.has(id)))return null;const trial=JSON.parse(JSON.stringify(s));trial.sessions[bid]=snapshot.run;trial.play.sessions[bid]=snapshot.play;if(!chapterRestore(trial))return null;}}
 return s;}catch{return null;}};
function studyTheme(sec=studySection(),chapter=studyState().chapter){return StudyThemes.forSection(sec,currentCourse().id===StrategistCourse.id,chapter);}
function fruitArt(){return `<i class="study-material-art">${sprites(studyTheme().art)}</i>`;}
function lessonPosition(i){const safe=CAT.objects(state.zone).filter(o=>zoneInfo().stations.every(st=>Math.abs(o.x-st[2])>6||Math.abs(o.y-st[3])>6)&&[[69,67],[47,57]].every(([x,y])=>Math.abs(o.x-x)>9||Math.abs(o.y-y)>9));return safe[(i*7+11)%safe.length];}
function enterStudyChapter(index){const s=studyState(),course=currentCourse(),bid=L.bank(state).id;if(!Number.isInteger(index)||!course.chapters[index])return;
 if(index!==s.chapter){const run=L.current(state),pool=new Set(CS.pool(s,course,L.bank(state).cards).map(c=>c.id));if(run&&run.cards.every(id=>pool.has(id))){s.practiceRuns??={};s.practiceRuns[s.chapter]=JSON.parse(JSON.stringify({run,play:A.session(state)}));}}
 if(!CS.enter(s,course,index))return;const cached=s.practiceRuns?.[index];if(cached){state.sessions[bid]=JSON.parse(JSON.stringify(cached.run));A.init(state).sessions[bid]=JSON.parse(JSON.stringify(cached.play));}else if(basicsReady()){L.bank(state).focus=studySection().id;L.start(state,Date.now(),true);A.session(state);}L.bank(state).focus=studySection().id;
 heldFruit=null;selectedPiece=null;selectedTool=null;activeQuest=null;state.zone=studyChapter().zone;close();renderWorld();resetCamera();save();}
function showChapterMap(){if(!currentCourse())return;const s=studyState(),course=currentCourse();modal(`<span class="eyebrow">按顺序，把知识织成一张地图</span><h2 id="dialogTitle">四章学习之旅</h2><p>各章可以自由选择，章内按小节顺序学习。完成本章基础知识交付后激活练习；章末达到90%记为本章通关。</p><div class="chapter-atlas">${course.chapters.map((ch,i)=>{const all=ch.sections.flatMap(sec=>sec.lessons),count=all.filter(l=>s.deposited.includes(l.id)).length,best=s.assessments.filter(a=>a.chapter===i).sort((a,b)=>b.correct/b.total-a.correct/a.total)[0],open=CS.unlocked(s,i);return `<button data-enter-chapter="${i}" class="chapter-map-card ${open?'':'locked'}" style="--chapter-image:url('assets/world-${ch.zone}.webp')"><span>第 ${i+1} 章 ${open?'':'· 尚未解锁'}</span><strong>${esc(ch.title)}</strong><small>${esc(ch.english)}</small><p>${ch.sections.length} 个小节 · 知识 ${count}/${all.length}${best?' · 章末 '+Math.floor(best.correct/best.total*100)+'%':''}</p></button>`;}).join('')}</div><div class="actions"><button id="continueChapter" class="primary">继续当前章节</button><button id="courseFromAPI">用我的资料生成课程</button></div>`,true);document.querySelectorAll('[data-enter-chapter]').forEach(el=>el.onclick=()=>enterStudyChapter(+el.dataset.enterChapter));$('continueChapter').onclick=close;$('courseFromAPI').onclick=showCourseImporter;}
function openStudyLesson(id,reference=false){const course=currentCourse(),s=studyState(),lesson=course.chapters.flatMap(ch=>ch.sections.flatMap(sec=>sec.lessons)).find(l=>l.id===id);if(!lesson)return;
 if(!reference&&!studySection().lessons.some(l=>l.id===id)){studyLocked();return;}
 if(reference&&!s.read.includes(id)){toast('这份知识还未收集，按小节顺序先去阅读它。');return;}
 modal(`<span class="eyebrow">${reference?'素材箱 · 随时翻阅':'基础学习 · 先读懂，不出题'}</span><h2 id="dialogTitle">${esc(lesson.title)}</h2><div class="lesson-explanation">${studyText(lesson.body)}</div>${lesson.example?`<div class="lesson-example"><strong>放到业务里看</strong><p>${esc(lesson.example)}</p></div>`:''}<details class="source-detail"><summary>对应的大纲目标与来源</summary><p>${esc(lesson.quote)}</p><p class="source">${esc(lesson.source)}</p><p class="muted">${esc(lesson.provenance)}</p></details><div class="actions"><button id="leaveLesson">${reference?'返回素材箱':'稍后再读'}</button>${reference?'':`<button id="collectLesson" class="primary">读懂了，收下这份学习素材</button>`}</div>`);
 $('leaveLesson').onclick=reference?showKnowledgeChest:close;
 if($('collectLesson'))$('collectLesson').onclick=()=>{CS.read(s,course,id);if(CS.collect(s,course,id)){heldFruit=id;close();render();save();toast('已收下「'+lesson.title+'」。放入本节知识装置，或打开装置整理。');}else toast('这份素材已经在背包或知识装置里了。');};
}
function putStudyFruit(id){if(!CS.deposit(studyState(),currentCourse(),id)){toast('这份素材属于其他小节，或还没有阅读收集。');return;}heldFruit=null;render();save();flash('知识整理 +1');}
function openStudyBasket(){const s=studyState(),sec=studySection(),theme=studyTheme(),n=sec.lessons.filter(l=>s.deposited.includes(l.id)).length,carried=sec.lessons.filter(l=>s.carried.includes(l.id));
 const slot=l=>`<button data-study-slot="${l.id}" class="knowledge-slot ${s.deposited.includes(l.id)?'filed':''}"><small>${s.deposited.includes(l.id)?'✓ 已整理':s.carried.includes(l.id)?'点击归位':'待阅读'}</small><strong>${esc(l.title)}</strong></button>`;
 const layout=theme.groups?theme.groups.map((name,i)=>`<section class="study-group"><h3>${esc(name)}</h3>${sec.lessons.filter(l=>StudyThemes.group(theme,l)===i).map(slot).join('')}</section>`).join(''):sec.lessons.map(slot).join('');
 modal(`<span class="eyebrow">小镇藏品 · 本节收集处</span><h2 id="dialogTitle">${esc(theme.container)}</h2><p class="device-learning-caption">学习内容 · Task ${esc(sec.id)} · ${esc(sec.title)}</p><div class="basket-count">${n}<small> / ${sec.lessons.length}</small></div><p>${esc(theme.instruction)}</p><p class="muted">点击待阅读条目可定位素材；已收集条目点击归位，已整理条目可随时重读。</p><div class="study-layout layout-${theme.kind} ${theme.groups?'has-groups':''}">${layout}</div><div class="actions"><button id="basketBack">回到场景</button><button id="depositCarried" ${carried.length?'':'disabled'}>整理背包中 ${carried.length} 份${esc(theme.item)}</button><button id="sealBasket" class="primary" ${n===sec.lessons.length&&!s.sealed.includes(sec.id)?'':'disabled'}>${esc(theme.action)}</button></div>`);
 document.querySelectorAll('[data-study-slot]').forEach(el=>el.onclick=()=>{const id=el.dataset.studySlot;if(s.deposited.includes(id)){openStudyLesson(id,true);return;}if(s.carried.includes(id)){putStudyFruit(id);openStudyBasket();return;}close();const i=sec.lessons.findIndex(l=>l.id===id),p=lessonPosition(i);pointXY(p.x,p.y);toast('先找到并阅读「'+sec.lessons[i].title+'」。');});
 $('basketBack').onclick=close;$('depositCarried').onclick=()=>{for(const l of carried)CS.deposit(s,currentCourse(),l.id);heldFruit=null;render();save();openStudyBasket();};$('sealBasket').onclick=()=>{if(!CS.seal(s,currentCourse()))return;close();render();save();toast(CS.learned(s,currentCourse())?'本章基础知识已整理完毕！去素材箱提交知识成果，激活练习。':theme.pack+'已收进素材箱。下一小节的学习素材已刷新。');};}
function showKnowledgeChest(){const course=currentCourse(),s=studyState();if(!course)return;modal(`<span class="eyebrow">知识素材箱 · 学过的内容随时能找回来</span><h2 id="dialogTitle">按章节与小节，整理完整的知识体系。</h2><div class="knowledge-tree">${course.chapters.map((ch,i)=>`<section><h3>第 ${i+1} 章 · ${esc(ch.title)}</h3>${ch.sections.map(sec=>{const n=sec.lessons.filter(l=>s.deposited.includes(l.id)).length;return `<details ${i===s.chapter?'open':''}><summary>${esc(StudyThemes.forSection(sec,course.id===StrategistCourse.id,i).pack)} · ${esc(sec.id+' '+sec.title)} <b>${n}/${sec.lessons.length}</b></summary><div class="knowledge-shelf">${sec.lessons.map(l=>`<button data-reread="${l.id}" ${s.read.includes(l.id)?'':'disabled'}>${esc(l.title)}<small>${s.read.includes(l.id)?'打开阅读':'尚未收集'}</small></button>`).join('')}</div></details>`;}).join('')}</section>`).join('')}</div><div class="actions"><button id="chestBack">返回场景</button><button id="submitKnowledge" class="primary" ${CS.learned(s,course)&&!s.submitted.includes(s.chapter)?'':'disabled'}>${s.submitted.includes(s.chapter)?'本章基础已交付':'交付本章知识成果，激活练习'}</button></div>`,true);document.querySelectorAll('[data-reread]').forEach(el=>el.onclick=()=>openStudyLesson(el.dataset.reread,true));$('chestBack').onclick=close;$('submitKnowledge').onclick=()=>{if(!CS.submit(s,course))return;startSectionPractice(0);toast('基础知识已交付。答题物件已激活，随时可以回素材箱复习。');};}
function startSectionPractice(index){if(!basicsReady()){studyLocked();return;}const s=studyState(),ch=studyChapter();if(!Number.isInteger(index)||!ch.sections[index])return;s.section=index;s.mode='practice';heldFruit=null;const bank=L.bank(state),sectionId=ch.sections[index].id;s.practiceStarted??=[];const refresh=bank.focus!==sectionId||!s.practiceStarted.includes(sectionId);bank.focus=sectionId;if(refresh){L.start(state,Date.now(),true);if(!s.practiceStarted.includes(sectionId))s.practiceStarted.push(sectionId);}A.session(state);activeQuest=null;selectedPiece=null;selectedTool=null;close();state.zone=ch.zone;renderWorld();resetCamera();save();}
function setStudyMode(mode){const s=studyState();if(mode!=='learn'&&!basicsReady()){studyLocked();return;}s.mode=mode;heldFruit=null;close();render();save();if(mode==='review'||mode==='mistakes')showStudyQueue(mode);}
function showStudyQueue(mode){if(!basicsReady()){studyLocked();return;}const s=studyState(),cards=L.bank(state).cards,list=mode==='mistakes'?CS.mistakes(s,currentCourse(),cards):CS.review(s,currentCourse(),cards);modal(`<span class="eyebrow">${mode==='mistakes'?'错题修复台':'记忆邮局 · 复习'}</span><h2 id="dialogTitle">${mode==='mistakes'?'把理解中的缺口补回来。':'按复习时间，重新回想学过的知识。'}</h2><p>${mode==='mistakes'?'错答后会进入这里。先回素材箱补基础，再独立答对，才移出待修复列表。':'只列出已经练过的本章题目，到期内容优先；展开原文或修正后完成，会记录为辅助练习。'}</p><div class="quest-list">${list.map(c=>`<button data-study-review="${c.id}"><span>${esc(c.q)}</span><small>${mode==='mistakes'?'待修复':s.records[c.id].due<=Date.now()?'已到复习时间':'可提前复习'}</small></button>`).join('')||'<p class="empty">暂时没有内容。先去完成本章练习吧。</p>'}</div><div class="actions"><button id="queueKnowledge">回知识素材箱</button><button id="queueBack">返回场景</button></div>`,true);document.querySelectorAll('[data-study-review]').forEach(el=>el.onclick=()=>{s.mode=mode;learningEncounter(L.card(state,el.dataset.studyReview),mode==='mistakes'?'错题修复':'本章复习');});$('queueKnowledge').onclick=showKnowledgeChest;$('queueBack').onclick=close;}
function startChapterAssessment(){if(!basicsReady()){studyLocked();return;}const s=studyState();if(!s.round)CS.beginAssessment(s,currentCourse(),L.bank(state).cards);if(!s.round){toast('本章没有可用题目，请先核对课程题库。');return;}s.mode='assessment';save();showChapterAssessment();}
function showChapterAssessment(){const s=studyState(),r=s.round;if(!r)return;if(r.answers.length===r.ids.length){const result=CS.finishAssessment(s),pass=result.correct/result.total>=.9;save();render();modal(`<span class="eyebrow">第 ${result.chapter+1} 章 · 完整测验</span><h2 id="dialogTitle">${result.correct} / ${result.total} · ${Math.floor(result.correct/result.total*100)}%</h2><p>${pass?'已达到90%，本章通关。其他章节可随时进入，知识素材箱会持续保留。':'还没有达到90%。先查看错题与基础资料，再进行新一轮完整测验。'}</p><p>本次覆盖本章全部题目，每题只记录首次提交；本地学习成绩不等同于官方考试成绩。</p><div class="actions"><button id="assessmentMistakes">查看错题</button><button id="assessmentDone" class="primary">${pass&&result.chapter<3?'进入下一章':'回到章节地图'}</button></div>`);$('assessmentMistakes').onclick=()=>setStudyMode('mistakes');$('assessmentDone').onclick=()=>{if(pass&&result.chapter<3)enterStudyChapter(result.chapter+1);else showChapterMap();};return;}
 const c=L.card(state,r.ids[r.answers.length]);learningEncounter(c,`章末测验 ${r.answers.length+1}/${r.ids.length}`,null,null,{independent:true,onSubmit:(ok,e)=>{if(!CS.answerAssessment(s,c.id,ok))return;chapterBaseAnswer(state,c.id,ok?c.a:'',Date.now(),false);save();modal(`<span class="eyebrow">章末测验 · 本题已提交</span><h2 id="dialogTitle">${ok?'本题正确':'本题加入错题修复台'}</h2><div class="encounter-resolution">${EncounterRules.summary(e).map(t=>`<p>${esc(t)}</p>`).join('')}</div><p>${esc(c.q)}</p><details class="source-detail"><summary>核对来源</summary><div class="preview-source formatted-source">${studyText(c.quote)}</div>${source(c)}</details><div class="actions"><button id="nextAssessment" class="primary">${r.answers.length===r.ids.length?'查看本章成绩':'下一题'}</button></div>`);$('nextAssessment').onclick=showChapterAssessment;}});
}
const chapterBaseAnswer=L.answer;
L.answer=function(s,id,chosen,now,assisted){const result=chapterBaseAnswer(s,id,chosen,now,assisted);if(s===state&&currentCourse()&&basicsReady()){const progress=studyState();if(progress.mode!=='assessment'&&CS.pool(progress,currentCourse(),L.bank(s).cards).some(c=>c.id===id))CS.record(progress,id,result.ok,progress.mode,!!assisted,now||Date.now());}return result;};
const chapterRenderLoot=renderLoot;
renderLoot=function(){if(!currentCourse()){chapterRenderLoot();return;}const s=studyState();if(s.mode!=='learn'&&basicsReady()){chapterRenderLoot();return;}
 const sec=studySection();$('features').innerHTML='';$('loot').innerHTML=sec.lessons.map((l,i)=>{if(s.carried.includes(l.id)||s.deposited.includes(l.id))return'';const p=lessonPosition(i);return `<button class="study-fruit" data-study-fruit="${l.id}" draggable="true" style="left:${p.x}%;top:${p.y}%" aria-label="阅读基础知识：${esc(l.title)}">${fruitArt()}<span>${i+1}</span><small>${esc(l.title)}</small></button>`;}).join('')+[0,1,2].map((_,i)=>`<button class="sleeping-question" data-sleeping-question="${i}" style="left:${40+i*13}%;top:${43+i*5}%" aria-label="未激活的答题物件">${sprites([3,11,9][i])}<small>🔒 练习</small></button>`).join('');
 $('stations').innerHTML=`<button class="study-basket-world" id="worldStudyBasket" data-drop="study-basket" style="left:69%;top:67%" aria-label="${esc(studyTheme().container)}"><i class="study-device-art">${sprites(studyTheme().device)}</i><strong>${sec.lessons.filter(l=>s.deposited.includes(l.id)).length}/${sec.lessons.length}</strong><small>${esc(studyTheme().container)}</small></button><button class="knowledge-chest-world" id="worldKnowledgeChest" style="left:47%;top:57%" aria-label="打开知识素材箱"><span>▣</span><strong>知识素材箱</strong>${CS.learned(s,currentCourse())&&!basicsReady()?'<small>全部收齐，来交付本章</small>':''}</button>`;
 document.querySelectorAll('[data-study-fruit]').forEach(el=>{el.onclick=e=>{if(Date.now()<suppressClick)return;e.stopPropagation();openStudyLesson(el.dataset.studyFruit);};bindDraggable(el,{lesson:el.dataset.studyFruit});});document.querySelectorAll('[data-sleeping-question]').forEach(el=>el.onclick=studyLocked);$('worldStudyBasket').onclick=()=>heldFruit?putStudyFruit(heldFruit):openStudyBasket();bindDrop($('worldStudyBasket'),'study-basket');$('worldKnowledgeChest').onclick=showKnowledgeChest;$('persistentChanges').innerHTML='';
};
const chapterDrag=applyDrag;
applyDrag=function(data,kind,category){if(currentCourse()){if(data?.lesson){if(!studyState().read.includes(data.lesson)){openStudyLesson(data.lesson);return;}if(kind==='study-basket')putStudyFruit(data.lesson);else toast('把学习素材送入本节知识装置。');return;}if(!basicsReady()){studyLocked();return;}}chapterDrag(data,kind,category);};
const chapterTray=renderTray;
renderTray=function(){if(!currentCourse()||studyState().mode!=='learn'){chapterTray();return;}const s=studyState(),ch=studyChapter(),sec=studySection();$('adventureTray').innerHTML=`<div class="chapter-section-tabs">${ch.sections.map((x,i)=>`<button data-study-section="${i}" class="${i===s.section?'active':''}"><b>${s.sealed.includes(x.id)?'✓ ':''}${esc(x.id)}</b><span>${esc(x.title)}</span><small>${x.lessons.filter(l=>s.deposited.includes(l.id)).length}/${x.lessons.length}</small></button>`).join('')}</div><div class="fruit-satchel"><strong>知识背包</strong>${sec.lessons.filter(l=>s.carried.includes(l.id)).map(l=>`<button data-carried-fruit="${l.id}" draggable="true" class="${heldFruit===l.id?'selected':''}">${fruitArt()}<span>${esc(l.title)}</span></button>`).join('')||'<span>先阅读场景中的学习素材，再到本节装置整理。</span>'}<button id="basketShortcut">打开${esc(studyTheme().container)}</button></div>`;document.querySelectorAll('[data-study-section]').forEach(el=>el.onclick=()=>{const i=+el.dataset.studySection;if(i>s.section&&!ch.sections.slice(0,i).every(x=>s.sealed.includes(x.id))){toast('先完成前面的小节知识整理，再开始下一节。');return;}s.section=i;heldFruit=null;render();save();});document.querySelectorAll('[data-carried-fruit]').forEach(el=>{el.onclick=()=>{heldFruit=heldFruit===el.dataset.carriedFruit?null:el.dataset.carriedFruit;renderHUD();};bindDraggable(el,{lesson:el.dataset.carriedFruit});});$('basketShortcut').onclick=openStudyBasket;};
const chapterDock=renderExamDock;
renderExamDock=function(){if(!currentCourse()){chapterDock();return;}let dock=$('chapterDock');if(!dock){dock=document.createElement('section');dock.id='chapterDock';$('adventureTray').appendChild(dock);}const s=studyState(),ch=studyChapter();dock.innerHTML=`<button id="chapterAtlasButton"><small>第 ${s.chapter+1}/6 章</small><strong>${esc(ch.title)}</strong></button><div class="chapter-mode-tabs">${[['learn','基础学习'],['practice','答题练习'],['review','复习'],['mistakes','错题']].map(([key,name])=>`<button data-study-mode="${key}" class="${s.mode===key?'active':''}">${name}${key!=='learn'&&!basicsReady()?' 🔒':''}</button>`).join('')}</div><button id="knowledgeChestButton">知识素材箱</button><button id="chapterFinalButton" class="primary">本章测验 · 90%通关</button>`;$('chapterAtlasButton').onclick=showChapterMap;$('knowledgeChestButton').onclick=showKnowledgeChest;$('chapterFinalButton').onclick=startChapterAssessment;document.querySelectorAll('[data-study-mode]').forEach(el=>el.onclick=()=>{if(el.dataset.studyMode==='practice'&&basicsReady())startSectionPractice(s.section);else setStudyMode(el.dataset.studyMode);});};
const chapterHUD=renderHUD;
renderHUD=function(){chapterHUD();const course=currentCourse();document.body.classList.toggle('chapter-course',!!course);if(!course)return;const s=studyState(),sec=studySection();$('welcomeTip').hidden=true;$('questNumber').textContent=`第 ${s.chapter+1} 章 · Task ${sec.id} · ${s.mode==='learn'?'先学基础':'学以致用'}`;$('questTitle').textContent=s.mode==='learn'?sec.title:$('questTitle').textContent;if(s.mode==='learn')$('sceneTip').textContent=heldFruit?'已拿起学习素材，点击或拖到本节知识装置。':'点击素材阅读基础知识 · 收集后到本节装置整理 · 带锁物件尚不能答题';renderExamDock();};
const chapterNPC=npc;
npc=function(i){if(!currentCourse()){chapterNPC(i);return;}if(i===0)showChapterMap();else if(i===1){if(basicsReady())showStudyQueue('review');else studyLocked();}else if(i===2)showKnowledgeChest();else openStudyBasket();};
const chapterZone=changeZone;
changeZone=function(zone){if(!currentCourse()){chapterZone(zone);return;}const i=currentCourse().chapters.findIndex(ch=>ch.zone===zone);if(i>=0)enterStudyChapter(i);};
const chapterStartQuiz=startExamQuiz,chapterOpenTask=openTask,chapterCouncil=showCouncilMenu,chapterInspect=inspectObject,chapterQuiz=showQuiz;
startExamQuiz=function(){if(currentCourse()){startChapterAssessment();return;}chapterStartQuiz();};
openTask=function(...args){if(currentCourse()&&!basicsReady()){studyLocked();return;}chapterOpenTask(...args);};
showCouncilMenu=function(){if(currentCourse()&&!basicsReady()){studyLocked();return;}chapterCouncil();};
inspectObject=function(id){if(currentCourse()&&!basicsReady()){studyLocked();return;}chapterInspect(id);};
showQuiz=function(...args){if(currentCourse()&&!basicsReady()){studyLocked();return;}chapterQuiz(...args);};
const chapterLegacyAtlas=showExamAtlas;
showExamAtlas=function(){if(currentCourse())showChapterMap();else chapterLegacyAtlas();};
const chapterInit=initExamWorld;
initExamWorld=function(){chapterInit();if(!currentCourse())return;const first=!state.chapterStudies?.[L.bank(state).id];studyState();state.zone=studyChapter().zone;state.guide=true;renderWorld();resetCamera();save();if(first)showChapterMap();};
const chapterPeople=renderNPCs;
renderNPCs=function(){if(!currentCourse()){chapterPeople();return;}const original=people.map(p=>({...p}));const roles=[['课程向导','章节与课程'],['复习邮差','复习与错题'],['知识管家','知识素材箱'],['学习导师','本节知识装置']];people.forEach((p,i)=>{p.job=roles[i][0];p.task=roles[i][1];});chapterPeople();people.forEach((p,i)=>Object.assign(p,original[i]));};
const chapterFinalHUD=renderHUD,chapterCompass=$('useCompass').onclick,chapterHome=$('home').onclick;
renderHUD=function(){chapterFinalHUD();if(!currentCourse()){$('home').onclick=chapterHome;$('useCompass').onclick=chapterCompass;$('questDetail').onclick=questDetail;$('questDetail').textContent='本批委托 ›';Object.entries(CAT.zones).forEach(([z,info])=>$(z+'Button').textContent=info.name);return;}
 currentCourse().chapters.forEach((ch,i)=>{const button=$(ch.zone+'Button');button.textContent='第'+(i+1)+'章 · '+CAT.zones[ch.zone].name;button.title=ch.title;});
 $('questDetail').textContent=studyState().mode==='learn'?studyTheme().container+' ›':'本批委托 ›';$('questDetail').onclick=studyState().mode==='learn'?openStudyBasket:questDetail;
 $('home').onclick=showChapterMap;
 $('useCompass').onclick=()=>{if(studyState().mode!=='learn'){chapterCompass();return;}const s=studyState(),i=studySection().lessons.findIndex(l=>!s.deposited.includes(l.id)&&!s.carried.includes(l.id));if(i<0){pointXY(69,67);toast('本节素材已在背包或知识装置里，去本节装置整理。');return;}const p=lessonPosition(i);pointXY(p.x,p.y);toast('这里藏着「'+studySection().lessons[i].title+'」，点开先阅读。');};
};
const chapterPracticeTray=renderTray;
renderTray=function(){chapterPracticeTray();if(!currentCourse()||studyState().mode==='learn')return;const s=studyState(),tabs=document.createElement('div');tabs.className='chapter-section-tabs practice-sections';tabs.innerHTML=studyChapter().sections.map((sec,i)=>{const cards=L.bank(state).cards.filter(c=>c.topic.startsWith('Task '+sec.id+' ·')),tried=cards.filter(c=>s.records[c.id]?.attempts).length;return `<button data-practice-section="${i}" class="${s.section===i?'active':''}"><b>${sec.id}</b><span>${esc(sec.title)}</span><small>练习 ${tried}/${cards.length}</small></button>`;}).join('');$('adventureTray').appendChild(tabs);document.querySelectorAll('[data-practice-section]').forEach(el=>el.onclick=()=>startSectionPractice(+el.dataset.practiceSection));};
